//! The workflow of a video generated by a video model: free-form nodes wired together, one per
//! project, saved in `.reel/workflow.json`; `workflow_canvas` shows and edits it. Text nodes hold
//! prompts; image / video nodes either hold an imported file or generate one, with the services in
//! Settings, from whatever is wired into them; a merge node joins videos (plus an optional audio
//! track) into the cut with ffmpeg. Results go to `assets/workflow/`, so the video's code and the
//! asset shelf can use them too.
//!
//! A node's output remembers the hash of everything upstream it was made from, so editing a
//! prompt makes it, and everything after it, stale.

use std::{
    collections::HashMap,
    fs,
    path::{Path, PathBuf},
    process::Command,
    time::{SystemTime, UNIX_EPOCH},
};

use anyhow::{Context as _, Result, anyhow, bail};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

use crate::{
    assets::{AssetKind, kind_of},
    config::Services,
    generate::{GenerateRequest, generate},
};

pub const KINDS: &[&str] = &["text", "image", "video", "audio", "merge"];

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct Workflow {
    #[serde(default)]
    pub nodes: Vec<Node>,
    #[serde(default)]
    pub edges: Vec<Edge>,
    #[serde(default)]
    next_id: i64,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Node {
    pub id: i64,
    /// text | image | video | audio | merge
    pub kind: String,
    pub title: String,
    pub x: f64,
    pub y: f64,
    #[serde(default)]
    pub text: String,
    /// Video length to ask for; `None` lets the service choose.
    #[serde(default)]
    pub seconds: Option<u32>,
    /// `1280x720`-style size to ask for; `None` lets the service choose.
    #[serde(default)]
    pub size: Option<String>,
    #[serde(default)]
    pub out: Option<Output>,
}

/// What a node holds: a file in the project, and what it was made from.
#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Output {
    /// Relative to the project folder.
    pub file: String,
    pub hash: String,
    /// A file the user brought in, not something generated here.
    #[serde(default)]
    pub imported: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Edge {
    pub id: i64,
    pub from: i64,
    pub to: i64,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub enum NodeStatus {
    /// Text, or an empty audio node: nothing to make.
    Idle,
    Done,
    /// Can be generated now.
    Ready,
    /// Has an older output; its inputs changed.
    Stale,
    /// Upstream not ready yet, or nothing to make it from.
    Waiting,
}

/// What a node hands downstream.
fn output_kind(kind: &str) -> &str {
    if kind == "merge" { "video" } else { kind }
}

/// Which node kinds take a given output. Image nodes only take prompts: the image services here
/// generate from text.
fn accepts(to: &str, output: &str) -> bool {
    matches!(
        (output, to),
        ("text", "image" | "video") | ("image", "video") | ("video", "merge") | ("audio", "merge")
    )
}

pub fn kind_name(kind: &str) -> String {
    match kind {
        "text" => rust_i18n::t!("canvas.kind_text"),
        "image" => rust_i18n::t!("canvas.kind_image"),
        "video" => rust_i18n::t!("canvas.kind_video"),
        "audio" => rust_i18n::t!("canvas.kind_audio"),
        _ => rust_i18n::t!("canvas.kind_merge"),
    }
    .to_string()
}

/// FNV-1a: stable across builds, unlike `DefaultHasher`, so saved hashes stay comparable.
fn hash(parts: &[&str]) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for part in parts {
        for b in part.bytes().chain([0]) {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x100000001b3);
        }
    }
    format!("{h:016x}")
}

fn stamp() -> u128 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |d| d.as_millis())
}

pub fn workflow_path(project: &Path) -> PathBuf {
    project.join(".reel").join("workflow.json")
}

/// Everything wired into a node, in wiring order; files are relative to the project.
#[derive(Default)]
struct Inputs {
    texts: Vec<String>,
    images: Vec<String>,
    videos: Vec<String>,
    audios: Vec<String>,
    /// Hashes of the upstream outputs, for the node's own hash.
    hashes: Vec<String>,
}

impl Workflow {
    pub fn load(project: &Path) -> Self {
        fs::read(workflow_path(project))
            .ok()
            .and_then(|data| serde_json::from_slice(&data).ok())
            .unwrap_or_default()
    }

    pub fn save(&self, project: &Path) -> Result<()> {
        let path = workflow_path(project);
        fs::create_dir_all(path.parent().context("bad path")?)?;
        fs::write(&path, serde_json::to_vec_pretty(self)?)
            .with_context(|| format!("writing {}", path.display()))
    }

    pub fn node(&self, id: i64) -> Option<&Node> {
        self.nodes.iter().find(|n| n.id == id)
    }

    pub fn node_mut(&mut self, id: i64) -> Option<&mut Node> {
        self.nodes.iter_mut().find(|n| n.id == id)
    }

    fn take_id(&mut self) -> i64 {
        let used = self
            .nodes
            .iter()
            .map(|n| n.id)
            .chain(self.edges.iter().map(|e| e.id))
            .max()
            .unwrap_or(0);
        self.next_id = self.next_id.max(used) + 1;
        self.next_id
    }

    pub fn add_node(&mut self, kind: &str, x: f64, y: f64) -> Result<i64> {
        if !KINDS.contains(&kind) {
            bail!("unknown node kind {kind}");
        }
        let n = self.nodes.iter().filter(|n| n.kind == kind).count();
        let id = self.take_id();
        self.nodes.push(Node {
            id,
            kind: kind.to_string(),
            title: format!("{} {}", kind_name(kind), n + 1),
            x,
            y,
            text: String::new(),
            seconds: None,
            size: None,
            out: None,
        });
        Ok(id)
    }

    /// Removes a node and its wires. Its files stay in `assets/`: the video may use them.
    pub fn delete_node(&mut self, id: i64) {
        self.nodes.retain(|n| n.id != id);
        self.edges.retain(|e| e.from != id && e.to != id);
    }

    /// Wires `from`'s output into `to`. Kinds must fit and the workflow stays acyclic.
    pub fn connect(&mut self, from: i64, to: i64) -> Result<()> {
        let (Some(a), Some(b)) = (self.node(from), self.node(to)) else {
            bail!("no such node");
        };
        if !accepts(&b.kind, output_kind(&a.kind)) {
            bail!(
                rust_i18n::t!(
                    "canvas.cannot_wire",
                    from = kind_name(&a.kind),
                    to = kind_name(&b.kind)
                )
                .to_string()
            );
        }
        if self.edges.iter().any(|e| e.from == from && e.to == to) {
            return Ok(());
        }
        // A path to → … → from would close a loop.
        let mut stack = vec![to];
        while let Some(n) = stack.pop() {
            if n == from {
                bail!(rust_i18n::t!("canvas.loop").to_string());
            }
            stack.extend(self.edges.iter().filter(|e| e.from == n).map(|e| e.to));
        }
        let id = self.take_id();
        self.edges.push(Edge { id, from, to });
        Ok(())
    }

    pub fn disconnect(&mut self, edge: i64) {
        self.edges.retain(|e| e.id != edge);
    }

    /// Copies a file into the project and puts it in node `id`; it stays as is until replaced.
    pub fn import_file(&mut self, project: &Path, id: i64, path: &Path) -> Result<()> {
        let kind = media_kind(path)?;
        let node = self.node(id).context("no such node")?;
        if kind != node.kind {
            bail!(
                rust_i18n::t!(
                    "canvas.wrong_file",
                    node = kind_name(&node.kind),
                    file = kind_name(kind)
                )
                .to_string()
            );
        }
        let name = path.file_name().context("bad path")?.to_string_lossy();
        let rel = format!("assets/workflow/{id}-{}-{name}", stamp());
        let target = project.join(&rel);
        fs::create_dir_all(target.parent().context("bad path")?)?;
        fs::copy(path, &target).with_context(|| format!("copying {}", path.display()))?;
        self.node_mut(id).context("no such node")?.out = Some(Output {
            hash: hash(&["import", &rel]),
            file: rel,
            imported: true,
        });
        Ok(())
    }

    /// A new node holding a dropped file, named after it.
    pub fn add_file_node(&mut self, project: &Path, path: &Path, x: f64, y: f64) -> Result<i64> {
        let id = self.add_node(media_kind(path)?, x, y)?;
        if let Err(error) = self.import_file(project, id, path) {
            self.delete_node(id);
            return Err(error);
        }
        if let Some(stem) = path.file_stem() {
            self.node_mut(id).context("no such node")?.title = stem.to_string_lossy().to_string();
        }
        Ok(id)
    }

    /// An imported file that nothing asks to replace: no wires in and no prompt of its own.
    fn imported(&self, n: &Node) -> bool {
        n.out.as_ref().is_some_and(|o| o.imported)
            && n.text.trim().is_empty()
            && !self.edges.iter().any(|e| e.to == n.id)
    }

    fn inputs(&self, id: i64) -> Inputs {
        let mut inp = Inputs::default();
        for e in self.edges.iter().filter(|e| e.to == id) {
            let Some(from) = self.node(e.from) else {
                continue;
            };
            if from.kind == "text" {
                if !from.text.trim().is_empty() {
                    inp.texts.push(from.text.trim().to_string());
                }
                continue;
            }
            let Some(out) = &from.out else { continue };
            inp.hashes.push(out.hash.clone());
            match output_kind(&from.kind) {
                "image" => inp.images.push(out.file.clone()),
                "video" => inp.videos.push(out.file.clone()),
                _ => inp.audios.push(out.file.clone()),
            }
        }
        inp
    }

    fn prompt(&self, n: &Node) -> String {
        let mut parts = self.inputs(n.id).texts;
        if !n.text.trim().is_empty() {
            parts.push(n.text.trim().to_string());
        }
        parts.join("\n")
    }

    /// What each node should be made from, as a hash; `None` when it cannot or need not be made
    /// now. Nodes are settled in wiring order: a node's hash needs its upstream's first.
    fn wanted(&self) -> HashMap<i64, Option<String>> {
        let mut wanted: HashMap<i64, Option<String>> = HashMap::new();
        let mut left: Vec<&Node> = self.nodes.iter().collect();
        while !left.is_empty() {
            let before = left.len();
            left.retain(|n| {
                let ready = self
                    .edges
                    .iter()
                    .filter(|e| e.to == n.id)
                    .all(|e| wanted.contains_key(&e.from) || self.node(e.from).is_none());
                if ready {
                    let h = self.hash_of(n, &wanted);
                    wanted.insert(n.id, h);
                }
                !ready
            });
            // `connect` keeps the workflow acyclic; a hand-edited file might not be.
            if left.len() == before {
                break;
            }
        }
        wanted
    }

    fn current(&self, n: &Node, wanted: &HashMap<i64, Option<String>>) -> bool {
        n.kind == "text"
            || self.imported(n)
            || matches!((&n.out, wanted.get(&n.id)), (Some(o), Some(Some(h))) if &o.hash == h)
    }

    fn hash_of(&self, n: &Node, wanted: &HashMap<i64, Option<String>>) -> Option<String> {
        if !["image", "video", "merge"].contains(&n.kind.as_str()) || self.imported(n) {
            return None;
        }
        // Upstream must be settled. A merge is local and free, so it takes what upstream has now
        // (even stale) and simply merges again once upstream is redone.
        let merge = n.kind == "merge";
        let unsettled = self.edges.iter().filter(|e| e.to == n.id).any(|e| {
            self.node(e.from).is_some_and(|u| {
                u.kind != "text" && (u.out.is_none() || !merge && !self.current(u, wanted))
            })
        });
        if unsettled {
            return None;
        }
        let inp = self.inputs(n.id);
        let prompt = self.prompt(n);
        let empty = match n.kind.as_str() {
            "merge" => inp.videos.is_empty(),
            _ => prompt.is_empty() && inp.images.is_empty(),
        };
        if empty {
            // Nothing to make it from (prompt cleared, wires gone): what it already has stays.
            return n.out.as_ref().map(|o| o.hash.clone());
        }
        let seconds = n.seconds.map(|s| s.to_string()).unwrap_or_default();
        let size = n.size.clone().unwrap_or_default();
        let mut parts: Vec<&str> = vec![&n.kind, &prompt, &seconds, &size];
        parts.extend(inp.hashes.iter().map(String::as_str));
        Some(hash(&parts))
    }

    pub fn status(&self) -> HashMap<i64, NodeStatus> {
        let wanted = self.wanted();
        self.nodes
            .iter()
            .map(|n| {
                let s = if n.kind == "text" || n.kind == "audio" && n.out.is_none() {
                    NodeStatus::Idle
                } else if self.current(n, &wanted) {
                    NodeStatus::Done
                } else if wanted.get(&n.id).is_some_and(Option::is_some) {
                    if n.out.is_some() {
                        NodeStatus::Stale
                    } else {
                        NodeStatus::Ready
                    }
                } else {
                    NodeStatus::Waiting
                };
                (n.id, s)
            })
            .collect()
    }

    /// The work to bring node `id` up to date, for a background thread; `None` if there is none.
    pub fn job(&self, id: i64) -> Option<Job> {
        let n = self.node(id)?;
        let wanted = self.wanted();
        let hash = wanted.get(&id)?.clone()?;
        if self.current(n, &wanted) {
            return None;
        }
        let inp = self.inputs(id);
        Some(Job {
            node: id,
            kind: n.kind.clone(),
            prompt: self.prompt(n),
            hash,
            seconds: n.seconds,
            size: n.size.clone(),
            image: inp.images.into_iter().next(),
            videos: inp.videos,
            audio: inp.audios.into_iter().next(),
        })
    }

    /// Puts a finished job's file into its node, if the node is still there.
    pub fn finish(&mut self, job: &Job, file: String) {
        if let Some(n) = self.node_mut(job.node) {
            n.out = Some(Output {
                file,
                hash: job.hash.clone(),
                imported: false,
            });
        }
    }

    /// The workflow for the agent: every node with its status, file and inputs, and the wires.
    pub fn describe(&self) -> Value {
        let status = self.status();
        let nodes: Vec<Value> = self
            .nodes
            .iter()
            .map(|n| {
                json!({
                    "id": n.id,
                    "kind": n.kind,
                    "title": n.title,
                    "text": n.text,
                    "seconds": n.seconds,
                    "size": n.size,
                    "status": status_name(status.get(&n.id).copied()),
                    "file": n.out.as_ref().map(|o| &o.file),
                    "imported": n.out.as_ref().is_some_and(|o| o.imported),
                    "inputs": self.edges.iter().filter(|e| e.to == n.id).map(|e| e.from).collect::<Vec<_>>(),
                })
            })
            .collect();
        json!({ "nodes": nodes, "edges": self.edges })
    }

    /// One edit from the agent (`reel workflow`): `build`, `set`, `connect`, `disconnect`,
    /// `delete` or `import`. All of it applies, or none of it (files already copied stay).
    pub fn apply(&mut self, project: &Path, op: &Value) -> Result<Value> {
        let mut workflow = self.clone();
        let answer = workflow.apply_op(project, op)?;
        *self = workflow;
        Ok(answer)
    }

    fn apply_op(&mut self, project: &Path, op: &Value) -> Result<Value> {
        let id = |key: &str| {
            op[key]
                .as_i64()
                .with_context(|| format!("`{key}` needs a node id"))
        };
        match op["op"].as_str().unwrap_or_default() {
            "build" => self.build(project, op),
            "set" => {
                let id = id("node")?;
                self.set(id, op)?;
                Ok(json!({ "node": id }))
            }
            "connect" => {
                self.connect(id("from")?, id("to")?)?;
                Ok(json!({}))
            }
            "disconnect" => {
                let (from, to) = (id("from")?, id("to")?);
                let before = self.edges.len();
                self.edges.retain(|e| !(e.from == from && e.to == to));
                if self.edges.len() == before {
                    bail!("node {from} is not wired into node {to}");
                }
                Ok(json!({}))
            }
            "delete" => {
                let ids: Vec<i64> = op["nodes"]
                    .as_array()
                    .context("`nodes` needs a list of node ids")?
                    .iter()
                    .map(|v| v.as_i64().context("`nodes` needs node ids"))
                    .collect::<Result<_>>()?;
                for id in &ids {
                    self.node(*id).with_context(|| format!("no node {id}"))?;
                    self.delete_node(*id);
                }
                Ok(json!({ "deleted": ids }))
            }
            "import" => {
                let file = PathBuf::from(op["file"].as_str().context("`file` needs a path")?);
                let file = project.join(file);
                let id = match op["node"].as_i64() {
                    Some(id) => {
                        self.import_file(project, id, &file)?;
                        id
                    }
                    None => {
                        let id = self.add_file_node(project, &file, 0., 0.)?;
                        self.layout(&[id]);
                        id
                    }
                };
                Ok(json!({ "node": id }))
            }
            other => bail!("unknown workflow operation `{other}`"),
        }
    }

    /// Title, prompt, length and size from `op`; `null` or `"auto"` clears length and size.
    fn set(&mut self, id: i64, op: &Value) -> Result<()> {
        let n = self.node_mut(id).with_context(|| format!("no node {id}"))?;
        let cleared = |v: &Value| v.is_null() || v.as_str() == Some("auto");
        if let Some(title) = op.get("title") {
            let title = title.as_str().context("`title` needs text")?.trim();
            if title.is_empty() {
                bail!("a node needs a title");
            }
            n.title = title.to_string();
        }
        if let Some(text) = op.get("text") {
            n.text = text.as_str().context("`text` needs text")?.to_string();
        }
        if let Some(seconds) = op.get("seconds") {
            n.seconds = match seconds {
                v if cleared(v) => None,
                v => Some(
                    v.as_u64()
                        .or_else(|| v.as_str().and_then(|s| s.trim().parse().ok()))
                        .filter(|s| (1..=60).contains(s))
                        .context("`seconds` needs a whole number from 1 to 60")?
                        as u32,
                ),
            };
        }
        if let Some(size) = op.get("size") {
            n.size = match size {
                v if cleared(v) => None,
                v => {
                    let size = v.as_str().context("`size` needs WIDTHxHEIGHT")?.trim();
                    let ok = size.split_once('x').is_some_and(|(w, h)| {
                        w.parse::<u32>().is_ok_and(|w| w > 0)
                            && h.parse::<u32>().is_ok_and(|h| h > 0)
                    });
                    if !ok {
                        bail!("`size` needs WIDTHxHEIGHT, like 1280x720");
                    }
                    Some(size.to_string())
                }
            };
        }
        Ok(())
    }

    /// New nodes and wires at once. A node may carry a `key`, a `file` to hold, and anything
    /// `set` takes; a wire's ends are node ids or keys of nodes made here. Answers key → id.
    fn build(&mut self, project: &Path, op: &Value) -> Result<Value> {
        let mut keys = serde_json::Map::new();
        let mut made = Vec::new();
        for spec in op["nodes"].as_array().into_iter().flatten() {
            let id = match spec["file"].as_str() {
                Some(file) => self.add_file_node(project, &project.join(file), 0., 0.)?,
                None => self.add_node(
                    spec["kind"]
                        .as_str()
                        .context("each node needs a `kind` or a `file`")?,
                    0.,
                    0.,
                )?,
            };
            self.set(id, spec)?;
            if let Some(key) = spec["key"].as_str()
                && keys.insert(key.to_string(), json!(id)).is_some()
            {
                bail!("two nodes have the key `{key}`");
            }
            made.push(id);
        }
        let end = |v: &Value| -> Result<i64> {
            match v {
                Value::Number(n) => n.as_i64().ok_or_else(|| anyhow!("bad node id {n}")),
                Value::String(key) => keys
                    .get(key)
                    .and_then(Value::as_i64)
                    .with_context(|| format!("no node with the key `{key}`")),
                _ => bail!("a wire's ends are node ids or keys"),
            }
        };
        for wire in op["edges"].as_array().into_iter().flatten() {
            self.connect(end(&wire["from"])?, end(&wire["to"])?)?;
        }
        self.layout(&made);
        Ok(json!({ "nodes": keys, "made": made }))
    }

    /// Places `ids` from left to right in wiring order, each column below what is already in it,
    /// so the person sees the flow. Nodes not listed keep where they are.
    fn layout(&mut self, ids: &[i64]) {
        const COLUMN: f64 = 380.;
        const ROW: f64 = 300.;
        // Depth: the longest chain of wires leading into a node.
        let mut depth: HashMap<i64, usize> = HashMap::new();
        let mut left: Vec<i64> = self.nodes.iter().map(|n| n.id).collect();
        while !left.is_empty() {
            let before = left.len();
            left.retain(|id| {
                let ins: Vec<i64> = self
                    .edges
                    .iter()
                    .filter(|e| e.to == *id)
                    .map(|e| e.from)
                    .collect();
                if ins.iter().all(|i| depth.contains_key(i)) {
                    let d = ins.iter().map(|i| depth[i] + 1).max().unwrap_or(0);
                    depth.insert(*id, d);
                    false
                } else {
                    true
                }
            });
            if left.len() == before {
                break;
            }
        }
        let placed: Vec<(f64, f64)> = self
            .nodes
            .iter()
            .filter(|n| !ids.contains(&n.id))
            .map(|n| (n.x, n.y))
            .collect();
        let left_edge = placed.iter().map(|p| p.0).fold(f64::INFINITY, f64::min);
        let left_edge = if left_edge.is_finite() { left_edge } else { 0. };
        let mut bottom: HashMap<usize, f64> = HashMap::new();
        for id in ids {
            let column = depth.get(id).copied().unwrap_or(0);
            let x = left_edge + column as f64 * COLUMN;
            let y = *bottom.entry(column).or_insert_with(|| {
                placed
                    .iter()
                    .filter(|p| (p.0 - x).abs() < COLUMN / 2.)
                    .map(|p| p.1 + ROW)
                    .fold(0., f64::max)
            });
            bottom.insert(column, y + ROW);
            if let Some(n) = self.node_mut(*id) {
                (n.x, n.y) = (x, y);
            }
        }
    }
}

pub fn status_name(status: Option<NodeStatus>) -> &'static str {
    match status {
        Some(NodeStatus::Done) => "done",
        Some(NodeStatus::Ready) => "ready",
        Some(NodeStatus::Stale) => "stale",
        Some(NodeStatus::Waiting) => "waiting",
        _ => "idle",
    }
}

fn media_kind(path: &Path) -> Result<&'static str> {
    match kind_of(path) {
        Some(AssetKind::Image) => Ok("image"),
        Some(AssetKind::Video) => Ok("video"),
        Some(AssetKind::Audio) => Ok("audio"),
        _ => bail!(
            rust_i18n::t!("canvas.unknown_file", name = path.display().to_string()).to_string()
        ),
    }
}

/// One node's generation, detached from the workflow so it can run off the UI thread.
#[derive(Clone, Debug)]
pub struct Job {
    pub node: i64,
    pub kind: String,
    prompt: String,
    /// What the node is made from; its output keeps it.
    pub hash: String,
    seconds: Option<u32>,
    size: Option<String>,
    /// The first image wired in: a video's first frame.
    image: Option<String>,
    videos: Vec<String>,
    audio: Option<String>,
}

impl Job {
    /// Makes the file; returns it relative to the project. Blocks for as long as the service takes.
    pub fn run(&self, services: &Services, project: &Path) -> Result<String> {
        let file = if self.kind == "merge" {
            self.merge(project)?
        } else {
            let request = GenerateRequest {
                project: String::new(),
                kind: self.kind.clone(),
                prompt: self.prompt.clone(),
                out: None,
                voice: None,
                size: self.size.clone(),
                seconds: self
                    .seconds
                    .filter(|_| self.kind == "video")
                    .map(|s| s.to_string()),
                image: self.image.clone().filter(|_| self.kind == "video"),
            };
            if request.prompt.trim().is_empty() && request.image.is_none() {
                bail!(rust_i18n::t!("canvas.needs_prompt").to_string());
            }
            // Image-to-video with no words: the services want a prompt, so ask for motion.
            let request = GenerateRequest {
                prompt: if request.prompt.trim().is_empty() {
                    "Bring this picture to life with natural motion.".into()
                } else {
                    request.prompt
                },
                ..request
            };
            let made = generate(services, &request, project)?;
            // Into `assets/workflow/`, named after the node, so its results sit together.
            let name = made.file_name().context("bad path")?.to_string_lossy();
            let target = project
                .join("assets/workflow")
                .join(format!("{}-{name}", self.node));
            fs::create_dir_all(target.parent().context("bad path")?)?;
            fs::rename(&made, &target)?;
            target
        };
        Ok(file
            .strip_prefix(project)
            .unwrap_or(&file)
            .to_string_lossy()
            .replace('\\', "/"))
    }

    /// The wired videos one after another at the first one's size, the first audio under them.
    fn merge(&self, project: &Path) -> Result<PathBuf> {
        if !crate::server::has_ffmpeg() {
            bail!("ffmpeg was not found on PATH");
        }
        let encoder = crate::server::video_encoder()
            .context("ffmpeg has no H.264 encoder: install a build with libx264 or libopenh264")?;
        let first = project.join(self.videos.first().context("no videos wired in")?);
        let (w, h) = video_size(&first)?;
        let out =
            project
                .join("assets/workflow")
                .join(format!("{}-merge-{}.mp4", self.node, stamp()));
        fs::create_dir_all(out.parent().context("bad path")?)?;
        let mut command = Command::new("ffmpeg");
        command.args(["-y", "-hide_banner", "-loglevel", "error"]);
        let mut filter = String::new();
        for (i, video) in self.videos.iter().enumerate() {
            command.arg("-i").arg(project.join(video));
            filter.push_str(&format!(
                "[{i}:v]scale={w}:{h}:force_original_aspect_ratio=decrease,pad={w}:{h}:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30,format=yuv420p[v{i}];"
            ));
        }
        for i in 0..self.videos.len() {
            filter.push_str(&format!("[v{i}]"));
        }
        filter.push_str(&format!("concat=n={}:v=1:a=0[v]", self.videos.len()));
        // Every input before the output options.
        if let Some(audio) = &self.audio {
            command.arg("-i").arg(project.join(audio));
        }
        command.args(["-filter_complex", &filter, "-map", "[v]"]);
        if self.audio.is_some() {
            let track = format!("{}:a", self.videos.len());
            // Padded with silence and cut at the picture's end.
            command.args(["-map", &track, "-af", "apad", "-shortest", "-c:a", "aac"]);
        }
        command.args(["-c:v", encoder]).arg(&out);
        let output = command.output().context("running ffmpeg")?;
        if !output.status.success() {
            bail!(
                "ffmpeg failed: {}",
                String::from_utf8_lossy(&output.stderr).trim()
            );
        }
        Ok(out)
    }
}

/// A video's width and height, from ffprobe.
fn video_size(file: &Path) -> Result<(u32, u32)> {
    let output = Command::new("ffprobe")
        .args(["-v", "error", "-select_streams", "v:0"])
        .args(["-show_entries", "stream=width,height", "-of", "csv=s=x:p=0"])
        .arg(file)
        .output()
        .context("running ffprobe")?;
    let text = String::from_utf8_lossy(&output.stdout);
    text.trim()
        .split_once('x')
        .and_then(|(w, h)| Some((w.parse().ok()?, h.trim().parse().ok()?)))
        // Encoders want even sizes.
        .map(|(w, h): (u32, u32)| (w & !1, h & !1))
        .with_context(|| format!("could not read the size of {}", file.display()))
}

/// Whether a generated project's list thumbnail is missing or older than its workflow file.
pub fn cover_is_stale(project: &Path) -> bool {
    let modified = |path: PathBuf| path.metadata().and_then(|m| m.modified()).ok();
    match (
        modified(crate::library::cover_path(project)),
        modified(workflow_path(project)),
    ) {
        (Some(cover), Some(workflow)) => workflow > cover,
        (None, Some(_)) => true,
        _ => false,
    }
}

/// A generated project's list thumbnail: the cut if a merge node has one, else the last picture or
/// clip in the workflow.
pub fn write_cover(project: &Path) -> Result<PathBuf> {
    let workflow = Workflow::load(project);
    let made = |kinds: &[&str]| {
        workflow
            .nodes
            .iter()
            .filter(|n| kinds.contains(&n.kind.as_str()))
            .filter_map(|n| n.out.as_ref())
            .next_back()
    };
    let out = made(&["merge"])
        .or_else(|| made(&["image", "video"]))
        .context("nothing in the workflow to show yet")?;
    let cover = crate::library::cover_path(project);
    fs::create_dir_all(cover.parent().context("bad path")?)?;
    let output = Command::new("ffmpeg")
        .args(["-y", "-hide_banner", "-loglevel", "error", "-i"])
        .arg(project.join(&out.file))
        .args(["-frames:v", "1", "-vf", "scale=320:-2"])
        .arg(&cover)
        .output()
        .context("running ffmpeg")?;
    if !output.status.success() {
        bail!(
            "ffmpeg failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    Ok(cover)
}

/// The first frame of a video as a PNG, cached under `.reel/posters/`, for the node's picture.
pub fn poster(project: &Path, video: &Path) -> Option<PathBuf> {
    let name = video.file_name()?.to_string_lossy();
    let poster = project.join(".reel/posters").join(format!("{name}.png"));
    if poster.is_file() {
        return Some(poster);
    }
    fs::create_dir_all(poster.parent()?).ok()?;
    let ok = Command::new("ffmpeg")
        .args(["-y", "-hide_banner", "-loglevel", "error", "-i"])
        .arg(video)
        .args(["-frames:v", "1", "-vf", "scale=480:-2"])
        .arg(&poster)
        .status()
        .is_ok_and(|s| s.success());
    ok.then_some(poster)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn text(workflow: &mut Workflow, t: &str) -> i64 {
        let id = workflow.add_node("text", 0., 0.).unwrap();
        workflow.node_mut(id).unwrap().text = t.into();
        id
    }

    #[test]
    fn wiring_rules() {
        let mut b = Workflow::default();
        let t = text(&mut b, "rain");
        let img = b.add_node("image", 0., 0.).unwrap();
        let vid = b.add_node("video", 0., 0.).unwrap();
        let merge = b.add_node("merge", 0., 0.).unwrap();
        b.connect(t, img).unwrap();
        b.connect(img, vid).unwrap();
        b.connect(vid, merge).unwrap();
        assert!(b.connect(img, t).is_err());
        assert!(b.connect(merge, img).is_err());
        b.connect(t, img).unwrap();
        assert_eq!(b.edges.len(), 3, "the same wire twice is one wire");
        b.delete_node(img);
        assert_eq!(b.edges.len(), 1);
        // Ids are never reused, so nothing inherits a deleted node's wires.
        assert!(b.add_node("image", 0., 0.).unwrap() > merge);
        assert!(b.add_node("nope", 0., 0.).is_err());
    }

    #[test]
    fn edits_upstream_make_downstream_stale() {
        let mut b = Workflow::default();
        let t = text(&mut b, "neon stage");
        let img = b.add_node("image", 0., 0.).unwrap();
        let vid = b.add_node("video", 0., 0.).unwrap();
        let merge = b.add_node("merge", 0., 0.).unwrap();
        for (x, y) in [(t, img), (img, vid), (vid, merge)] {
            b.connect(x, y).unwrap();
        }
        let s = b.status();
        assert_eq!(s[&t], NodeStatus::Idle);
        assert_eq!(s[&img], NodeStatus::Ready);
        assert_eq!(s[&vid], NodeStatus::Waiting);
        assert!(b.job(vid).is_none());

        let job = b.job(img).unwrap();
        assert_eq!(job.prompt, "neon stage");
        b.finish(&job, "assets/workflow/a.png".into());
        assert_eq!(b.status()[&img], NodeStatus::Done);
        let job = b.job(vid).unwrap();
        assert_eq!(job.image.as_deref(), Some("assets/workflow/a.png"));
        b.finish(&job, "assets/workflow/v.mp4".into());
        let job = b.job(merge).unwrap();
        assert_eq!(job.videos, ["assets/workflow/v.mp4"]);
        b.finish(&job, "assets/workflow/m.mp4".into());
        assert!(
            b.status()
                .values()
                .all(|s| matches!(s, NodeStatus::Done | NodeStatus::Idle))
        );

        b.node_mut(t).unwrap().text = "blue stage".into();
        let s = b.status();
        assert_eq!(s[&img], NodeStatus::Stale);
        assert_eq!(s[&vid], NodeStatus::Waiting);
        assert_eq!(s[&merge], NodeStatus::Done, "merges what upstream has");
        // Clearing the prompt leaves the picture as it is.
        b.node_mut(t).unwrap().text.clear();
        assert_eq!(b.status()[&img], NodeStatus::Done);
        // A video setting is part of what the video is made from.
        b.node_mut(vid).unwrap().seconds = Some(8);
        assert_eq!(b.status()[&vid], NodeStatus::Stale);

        // It survives a save.
        let dir = std::env::temp_dir().join(format!("lumireel-workflow-{}", std::process::id()));
        b.save(&dir).unwrap();
        let back = Workflow::load(&dir);
        assert_eq!(back.nodes, b.nodes);
        assert_eq!(back.status(), b.status());
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn merges_clips_of_different_sizes_with_music() {
        if !crate::server::has_ffmpeg() {
            return;
        }
        let dir =
            std::env::temp_dir().join(format!("lumireel-workflow-merge-{}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        let make = |name: &str, input: &str| {
            let ok = Command::new("ffmpeg")
                .args(["-y", "-loglevel", "error", "-f", "lavfi", "-i", input])
                .arg(dir.join(name))
                .status()
                .unwrap();
            assert!(ok.success());
            dir.join(name)
        };
        let a = make("a.mp4", "testsrc=s=320x180:r=30:d=1");
        let b = make("b.mp4", "testsrc=s=180x320:r=30:d=1");
        let music = make("m.wav", "sine=f=440:d=5");
        let mut workflow = Workflow::default();
        let merge = workflow.add_node("merge", 0., 0.).unwrap();
        for file in [&a, &b, &music] {
            let id = workflow.add_file_node(&dir, file, 0., 0.).unwrap();
            workflow.connect(id, merge).unwrap();
        }
        let job = workflow.job(merge).unwrap();
        let file = job.run(&Services::default(), &dir).unwrap();
        assert!(file.starts_with("assets/workflow/"), "{file}");
        assert_eq!(video_size(&dir.join(&file)).unwrap(), (320, 180));
        assert!(poster(&dir, &dir.join(&file)).is_some());
        workflow.finish(&job, file);
        assert_eq!(workflow.status()[&merge], NodeStatus::Done);
        // The cut is the project's thumbnail, redrawn when the workflow changes.
        workflow.save(&dir).unwrap();
        assert!(cover_is_stale(&dir));
        let cover = write_cover(&dir).unwrap();
        assert!(image::image_dimensions(&cover).unwrap().0 == 320);
        assert!(!cover_is_stale(&dir));
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn the_agent_builds_and_edits_a_workflow() {
        let dir =
            std::env::temp_dir().join(format!("lumireel-workflow-agent-{}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        fs::write(dir.join("girl.png"), b"\x89PNG").unwrap();
        let mut b = Workflow::default();
        let built = b
            .apply(
                &dir,
                &json!({"op": "build",
                    "nodes": [
                        {"key": "look", "file": "girl.png", "title": "Heroine"},
                        {"key": "act", "kind": "text", "text": "she turns and smiles"},
                        {"key": "clip", "kind": "video", "seconds": 6, "size": "720x1280"},
                        {"key": "cut", "kind": "merge"}],
                    "edges": [
                        {"from": "look", "to": "clip"}, {"from": "act", "to": "clip"},
                        {"from": "clip", "to": "cut"}]}),
            )
            .unwrap();
        let key = |k: &str| built["nodes"][k].as_i64().unwrap();
        let (look, clip, cut) = (key("look"), key("clip"), key("cut"));
        let n = b.node(clip).unwrap();
        assert_eq!((n.seconds, n.size.as_deref()), (Some(6), Some("720x1280")));
        assert_eq!(b.node(look).unwrap().title, "Heroine");
        // Laid out left to right in wiring order.
        let x = |id| b.node(id).unwrap().x;
        assert!(x(look) < x(clip) && x(clip) < x(cut));
        let shown = b.describe();
        let clip_shown = shown["nodes"]
            .as_array()
            .unwrap()
            .iter()
            .find(|n| n["id"] == clip)
            .unwrap();
        assert_eq!(clip_shown["status"], "ready");
        assert_eq!(clip_shown["inputs"].as_array().unwrap().len(), 2);

        b.apply(
            &dir,
            &json!({"op": "set", "node": clip, "seconds": "auto", "text": "slowly"}),
        )
        .unwrap();
        assert_eq!(b.node(clip).unwrap().seconds, None);
        assert_eq!(b.node(clip).unwrap().text, "slowly");

        // A bad edit changes nothing, even after parts of it went through.
        let before = b.nodes.clone();
        let bad = json!({"op": "build", "nodes": [{"key": "x", "kind": "text"}],
            "edges": [{"from": cut, "to": "x"}]});
        assert!(b.apply(&dir, &bad).is_err());
        assert_eq!(b.nodes, before);
        assert!(
            b.apply(&dir, &json!({"op": "set", "node": clip, "size": "big"}))
                .is_err()
        );

        b.apply(&dir, &json!({"op": "disconnect", "from": clip, "to": cut}))
            .unwrap();
        assert!(
            b.apply(&dir, &json!({"op": "disconnect", "from": clip, "to": cut}))
                .is_err()
        );
        b.apply(&dir, &json!({"op": "delete", "nodes": [cut]}))
            .unwrap();
        assert!(b.node(cut).is_none());
        let imported = b
            .apply(&dir, &json!({"op": "import", "file": "girl.png"}))
            .unwrap();
        assert!(b.node(imported["node"].as_i64().unwrap()).is_some());
        assert!(b.apply(&dir, &json!({"op": "fly"})).is_err());
        let _ = fs::remove_dir_all(&dir);
    }

    #[test]
    fn imports_stay_until_asked_to_change() {
        let dir =
            std::env::temp_dir().join(format!("lumireel-workflow-imp-{}", std::process::id()));
        fs::create_dir_all(&dir).unwrap();
        let pic = dir.join("cat.png");
        fs::write(&pic, b"\x89PNG").unwrap();
        let mut b = Workflow::default();
        let id = b.add_file_node(&dir, &pic, 0., 0.).unwrap();
        let n = b.node(id).unwrap();
        assert_eq!((n.kind.as_str(), n.title.as_str()), ("image", "cat"));
        assert!(dir.join(&n.out.as_ref().unwrap().file).is_file());
        assert_eq!(b.status()[&id], NodeStatus::Done);
        // Wrong kind of file, and unknown files, are refused.
        let vid = b.add_node("video", 0., 0.).unwrap();
        assert!(b.import_file(&dir, vid, &pic).is_err());
        assert!(b.add_file_node(&dir, &dir.join("x.txt"), 0., 0.).is_err());
        // A prompt of its own turns it into something to generate.
        b.node_mut(id).unwrap().text = "make it a dog".into();
        assert_eq!(b.status()[&id], NodeStatus::Stale);
        let _ = fs::remove_dir_all(&dir);
    }
}
